"""9s62 · TEST THE STORE: the device's own IndexedDB put through its paces, each line a measurement, in Troubleshoot."""
FOLD = r'''<details class="fold panel" id="fold-storetest">
          <summary><span class="n">8</span><span class="t">🧪 Test the store</span><span class="s" id="stTestState">when the library misbehaves</span></summary>
          <div class="fold-body">
            <p data-stt="lede">The Forge keeps your apps, your files and the Studio's work in this device's own store, IndexedDB. Browsers differ in how they keep it: Safari and WebKit, Chrome and Silk, Firefox, and the app shells on each device. This test writes to a scratch store of its own, reads back, counts, removes, and reports each step, so a fault is named before it costs you work. Nothing of yours is touched.</p>
            <div class="row"><button type="button" class="stone solid" id="stTestGo">🧪 Run the test</button><button type="button" class="solid" id="stTestCopy">Keep the report as a note</button></div>
            <div id="stTestOut" class="trouble-out" style="margin-top:8px"></div>
          </div>
        </details>
        '''
JS = r'''<script id="cd-9s62-storetest-js">
/* 9s62 · TEST THE STORE. Her ask: a testing framework for the library system, for reliability across IndexedDB implementations.
   Inside the app: a scratch database (forge-selftest) is opened, a record of a megabyte written and read back whole, a cursor
   counted, a transaction made to abort and checked to have changed nothing, a record removed, the database deleted; beside it,
   the browser's own reading of its storage, whether it will keep the store (persist), whether it can unpack and pack a zip
   (DecompressionStream, CompressionStream) and make a fingerprint (crypto.subtle), and whether the app library opens and reads
   its own records. Each line is a measurement with a tick or a cross and the time it took. The same checks run from the
   repository's tests (tests/) in a headless browser, on every build. */
(function(){
  function $(id){ return document.getElementById(id); }
  function fr(){ return document.documentElement.lang==='fr'; }
  function T(en,f){ return fr()?f:en; }
  function esc(t){ return String(t==null?'':t).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
  var LINES=[];
  function L(ok, text, ms){ LINES.push({ok:ok, text:text, ms:ms}); paint(); }
  function paint(){ var o=$('stTestOut'); if(!o) return; o.innerHTML=LINES.map(function(l){ return '<div class="tl '+(l.ok===true?'ok':(l.ok===false?'bad':'note'))+'">'+(l.ok===true?'✓':(l.ok===false?'✗':'·'))+' '+esc(l.text)+(l.ms!=null?' <span class="muted">('+l.ms+' ms)</span>':'')+'</div>'; }).join(''); }
  function now(){ return (window.performance&&performance.now)?performance.now():Date.now(); }
  function step(name, fn){ var t0=now(); return Promise.resolve().then(fn).then(function(r){ L(true, name+(r?': '+r:''), Math.round(now()-t0)); return true; }, function(e){ L(false, name+': '+String(e&&(e.message||e.name)||e), Math.round(now()-t0)); return false; }); }
  function openScratch(){ return new Promise(function(res,rej){ if(!window.indexedDB) return rej(new Error('IndexedDB is not here')); var r=indexedDB.open('forge-selftest',1); r.onupgradeneeded=function(){ try{ r.result.createObjectStore('t',{keyPath:'id'}); }catch(e){} }; r.onsuccess=function(){ res(r.result); }; r.onerror=function(){ rej(r.error||new Error('open refused')); }; r.onblocked=function(){ rej(new Error('open blocked')); }; }); }
  function tx(d, mode, fn){ return new Promise(function(res,rej){ var t=d.transaction('t',mode), out; try{ out=fn(t.objectStore('t'), t); }catch(e){ rej(e); return; } t.oncomplete=function(){ res(out&&out.result!==undefined?out.result:out); }; t.onerror=function(){ rej(t.error||new Error('transaction error')); }; t.onabort=function(){ rej(t.error||new Error('aborted')); }; }); }
  function run(){ LINES=[]; paint(); var b=$('stTestGo'); b.disabled=true; var d=null, big=null;
    var p=step(T('The browser’s own reading of its storage','La lecture du navigateur de son stockage'), function(){ if(!(navigator.storage&&navigator.storage.estimate)) return T('not offered by this browser (older WebKit); the Forge measures its own count instead','pas offerte par ce navigateur (ancien WebKit) ; la Forge compte elle-même'); return navigator.storage.estimate().then(function(e){ return (e.usage/1048576).toFixed(1)+' MB '+T('used of about ','utilisés sur environ ')+(e.quota/1048576).toFixed(0)+' MB'; }); })
    .then(function(){ return step(T('Will the device keep the store? (persist)','L’appareil gardera-t-il le stockage ? (persist)'), function(){ if(!(navigator.storage&&navigator.storage.persisted)) return T('not asked by this browser; the store may be cleared under pressure, the library file brings the apps back','non demandé par ce navigateur ; le stockage peut être effacé sous pression, le fichier de bibliothèque ramène les apps'); return navigator.storage.persisted().then(function(p){ return p?T('yes, marked persistent','oui, marqué persistant'):T('not yet (the Forge asks when the library file is opened)','pas encore (la Forge le demande à l’ouverture de la bibliothèque)'); }); }); })
    .then(function(){ return step(T('Unpacking a zip (DecompressionStream)','Déballer un zip (DecompressionStream)'), function(){ if(typeof DecompressionStream!=='function') throw new Error(T('missing: the app library file cannot be unpacked here; choose each app’s own file instead','manquant : le fichier de bibliothèque ne peut pas être déballé ici ; choisissez le fichier de chaque app')); new DecompressionStream('deflate-raw'); return T('present','présent'); }); })
    .then(function(){ return step(T('Packing a zip (CompressionStream)','Emballer un zip (CompressionStream)'), function(){ if(typeof CompressionStream!=='function') return T('missing: zips are made uncompressed, which still opens everywhere','manquant : les zips sont faits sans compression, ce qui s’ouvre partout'); new CompressionStream('deflate-raw'); return T('present','présent'); }); })
    .then(function(){ return step(T('A fingerprint (SHA-256)','Une empreinte (SHA-256)'), function(){ var u=new TextEncoder().encode('The Forge'); return Promise.resolve(window.__forgeLibSha(u)).then(function(h){ if(!/^[0-9a-f]{64}$/.test(h)) throw new Error('bad digest'); return Promise.resolve(window.__forgeLibSha(u,true)).then(function(h2){ if(h!==h2) throw new Error(T('the browser’s and the Forge’s own sums disagree','les sommes du navigateur et de la Forge diffèrent')); return h.slice(0,12)+'… '+T('both ways agree','les deux voies concordent'); }); }); }); })
    .then(function(){ return step(T('Open a scratch store','Ouvrir un stockage d’essai'), function(){ return openScratch().then(function(x){ d=x; return 'forge-selftest'; }); }); })
    .then(function(ok){ if(!d) return; big=new Uint8Array(1048576); for(var i=0;i<big.length;i+=4096) big[i]=i&255;
      return step(T('Write one megabyte','Écrire un mégaoctet'), function(){ return tx(d,'readwrite',function(s){ s.put({id:'big', bytes:big.buffer, at:Date.now()}); }).then(function(){ return '1 MB'; }); })
      .then(function(){ return step(T('Read it back whole','Le relire entier'), function(){ return tx(d,'readonly',function(s){ return s.get('big'); }).then(function(r){ if(!r||!r.bytes) throw new Error('not found'); var u=new Uint8Array(r.bytes); if(u.length!==big.length) throw new Error('length '+u.length); for(var i=0;i<u.length;i+=4096){ if(u[i]!==(i&255)) throw new Error('byte '+i+' differs'); } return T('every byte the same','chaque octet identique'); }); }); })
      .then(function(){ return step(T('Write twenty small records and count them with a cursor','Écrire vingt petits enregistrements et les compter au curseur'), function(){ return tx(d,'readwrite',function(s){ for(var i=0;i<20;i++) s.put({id:'r'+i, n:i}); }).then(function(){ return tx(d,'readonly',function(s,t){ var n=0, c=s.openCursor(); c.onsuccess=function(){ var k=c.result; if(k){ n++; k.continue(); } else t.__n=n; }; return {get result(){ return t.__n; }}; }).then(function(n){ if(n!==21) throw new Error('counted '+n); return '21'; }); }); }); })
      .then(function(){ return step(T('An aborted transaction changes nothing','Une transaction annulée ne change rien'), function(){ return new Promise(function(res,rej){ var t=d.transaction('t','readwrite'), s=t.objectStore('t'); s.put({id:'r0', n:999}); s.put({id:'ghost', n:1}); t.abort(); t.onabort=function(){ res(); }; t.oncomplete=function(){ rej(new Error('completed despite abort')); }; }).then(function(){ return tx(d,'readonly',function(s){ return s.get('r0'); }).then(function(r){ if(!r||r.n!==0) throw new Error('r0 changed'); return tx(d,'readonly',function(s){ return s.get('ghost'); }).then(function(g){ if(g) throw new Error('ghost written'); return T('r0 kept its value, ghost never written','r0 a gardé sa valeur, ghost jamais écrit'); }); }); }); }); })
      .then(function(){ return step(T('Remove a record','Retirer un enregistrement'), function(){ return tx(d,'readwrite',function(s){ s.delete('big'); }).then(function(){ return tx(d,'readonly',function(s){ return s.get('big'); }).then(function(r){ if(r) throw new Error('still there'); return T('gone','parti'); }); }); }); })
      .then(function(){ return step(T('Close and delete the scratch store','Fermer et supprimer le stockage d’essai'), function(){ try{ d.close(); }catch(e){} return new Promise(function(res,rej){ var r=indexedDB.deleteDatabase('forge-selftest'); r.onsuccess=function(){ res(T('deleted','supprimé')); }; r.onerror=function(){ rej(r.error); }; r.onblocked=function(){ res(T('deletion waits for another tab','la suppression attend un autre onglet')); }; }); }); }); })
    .then(function(){ return step(T('The app library opens and lists its records','La bibliothèque s’ouvre et liste ses enregistrements'), function(){ if(!window.__forgeLib) throw new Error('library code missing'); return window.__forgeLib.meta().then(function(M){ var ids=Object.keys(M); return ids.length?ids.map(function(k){ return k+' '+(M[k].version||''); }).join(', '):T('no copy kept yet (that is not a fault)','aucune copie gardée (ce n’est pas une faute)'); }); }); })
    .then(function(){ return step(T('Each kept copy reads back at its recorded size','Chaque copie gardée se relit à sa taille'), function(){ return window.__forgeLib.meta().then(function(M){ var ids=Object.keys(M), p=Promise.resolve(), out=[]; ids.forEach(function(id){ p=p.then(function(){ return window.__forgeLib.bytes(id).then(function(b){ var n=b?b.byteLength:0; if(n!==(M[id].size||0)) throw new Error(id+': '+n+' bytes, expected '+M[id].size); out.push(id); }); }); }); return p.then(function(){ return out.length?out.length+T(' copies whole',' copies entières'):T('nothing to read','rien à lire'); }); }); }); })
    .then(function(){ var bad=LINES.filter(function(l){ return l.ok===false; }).length; L(bad?false:true, bad?T(bad+' step'+(bad===1?'':'s')+' failed: the lines above say which and what to do', bad+' étape'+(bad===1?'':'s')+' en échec : les lignes ci-dessus disent lesquelles et quoi faire'):T('Every step passed: this device keeps the Forge’s work faithfully.','Chaque étape a réussi : cet appareil garde fidèlement le travail de la Forge.')); try{ FORGE.state('stTestState', bad?(bad+T(' failed',' en échec')):T('all passed','tout a réussi'), bad?'warn':'ok'); }catch(e){} b.disabled=false; try{ FORGE.diary('test', T('store test: ','test du stockage : ')+(bad?bad+T(' failed',' en échec'):T('all passed','tout a réussi'))); }catch(e){} })
    .catch(function(e){ L(false, String(e&&e.message||e)); b.disabled=false; });
    return p; }
  function keep(){ var txt=LINES.map(function(l){ return (l.ok===true?'OK   ':(l.ok===false?'FAIL ':'     '))+l.text+(l.ms!=null?' ('+l.ms+' ms)':''); }).join('\n'); if(!txt) return; try{ FORGE.files.push({name:'store-test-'+new Date().toISOString().slice(0,10)+'.txt', doc:'<pre>'+esc(txt)+'</pre>', text:txt, kind:'text'}); FORGE.paint(); }catch(e){} try{ if(navigator.clipboard) navigator.clipboard.writeText(txt).catch(function(){}); }catch(e){} L(null, T('Kept in the Library, and copied.','Gardé dans la Bibliothèque, et copié.')); }
  function seat(){ var tr=$('fold-trouble'); if(!tr||$('fold-storetest')) return !!$('fold-storetest'); var cmp=$('fold-compare'); (cmp||tr).insertAdjacentHTML('afterend', ''' + repr(FOLD) + '''); $('stTestGo').onclick=run; $('stTestCopy').onclick=keep; return true; }
  function start(){ if(!seat()) setTimeout(start, 900); }
  window.__forgeStoreTest={ run:run, lines:function(){ return LINES.slice(); } };
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded', start); else start();
})();
</script>
<style id="cd-9s62-storetest-css">#fold-storetest .tl{font:13px/1.55 var(--cd-sans,system-ui,sans-serif);padding:2px 0}#fold-storetest .tl.ok{color:#1d6b3a}#fold-storetest .tl.bad{color:#9c2a2a;font-weight:600}body[data-theme="night"] #fold-storetest .tl.ok{color:#9fe0b4}body[data-theme="night"] #fold-storetest .tl.bad{color:#f0a0a0}</style>
'''
def apply(P):
    P.insert_before('<script id="cd-9s61-studio">', JS, 'store test block')
